import java.util.*;

class Solution {
    public int longestRising(int[] nums) {
        int[] tails = new int[nums.length];   // tails[k] = smallest end of a rising pick of length k+1
        int size = 0;
        for (int x : nums) {
            int lo = 0, hi = size;            // first index with tails[idx] >= x
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails[mid] < x) lo = mid + 1;
                else hi = mid;
            }
            tails[lo] = x;
            if (lo == size) size++;           // extended the longest pick
        }
        return size;
    }
}

