function longestRising(nums) {
  const n = nums.length, best = new Array(n).fill(1); let ans = 0;
  for (let i = 0; i < n; i++) { for (let j = 0; j < i; j++) if (nums[j] < nums[i] && best[j] + 1 > best[i]) best[i] = best[j] + 1; ans = Math.max(ans, best[i]); }
  return ans;
}
